def parse_music(music_string: str) -> List[int]:
    def map_duration(note: str) -> int:
        if note == 'o':
            return 4
        elif note == 'o|':
            return 2
        elif note == '.|':
            return 1
        else:
            raise ValueError("Invalid note duration symbol")

    def validate_input_string(music_string: str) -> bool:
        valid_symbols = ['o', 'o|', '.|']
        notes = music_string.split()
        for note in notes:
            if note not in valid_symbols:
                return False
        return True

    if not validate_input_string(music_string):
        raise ValueError("Input string is not correctly formatted according to the legend")

    result = []
    for note in music_string.split():
        result.append(map_duration(note))

    return result

